{
  "name": "@code-yeongyu/comment-checker",
  "version": "0.8.2",
  "description": "Multi-language comment detection hook for Claude Code/OpenCode. Native binary powered by tree-sitter.",
  "main": "index.js",
  "bin": {
    "comment-checker": "cli.js"
  },
  "files": [
    "index.js",
    "cli.js",
    "postinstall.js"
  ],
  "scripts": {
    "postinstall": "node postinstall.js"
  },
  "optionalDependencies": {
    "@code-yeongyu/comment-checker-darwin-arm64": "0.8.2",
    "@code-yeongyu/comment-checker-darwin-x64": "0.8.2",
    "@code-yeongyu/comment-checker-linux-arm64": "0.8.2",
    "@code-yeongyu/comment-checker-linux-x64": "0.8.2",
    "@code-yeongyu/comment-checker-win32-x64": "0.8.2"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/code-yeongyu/go-claude-code-comment-checker.git"
  },
  "keywords": [
    "comment-checker",
    "tree-sitter",
    "claude-code",
    "opencode",
    "hook",
    "linter"
  ],
  "author": "YeonGyu Kim <yeongyu.gim@gmail.com>",
  "license": "MIT",
  "bugs": {
    "url": "https://github.com/code-yeongyu/go-claude-code-comment-checker/issues"
  },
  "homepage": "https://github.com/code-yeongyu/go-claude-code-comment-checker#readme",
  "engines": {
    "node": ">=18"
  }
}
